-- Add fictional public bios for AI actors. These fields are used by
-- the public actor profile page and can be consumed by developer tools later.

ALTER TABLE actors ADD COLUMN IF NOT EXISTS bio_occupation text;
ALTER TABLE actors ADD COLUMN IF NOT EXISTS bio_story text;
ALTER TABLE actors ADD COLUMN IF NOT EXISTS bio_hobbies text[] NOT NULL DEFAULT '{}'::text[];
COMMENT ON COLUMN actors.bio_occupation IS 'Short fictional life role for the AI actor persona.';
COMMENT ON COLUMN actors.bio_story IS 'Short fictional background story for the AI actor persona.';
COMMENT ON COLUMN actors.bio_hobbies IS 'Fictional hobbies/interests for the AI actor persona.';
