UPDATE actors AS a
SET
  bio_occupation = COALESCE(NULLIF(a.bio_occupation, ''), bios.bio_occupation),
  bio_story = COALESCE(NULLIF(a.bio_story, ''), bios.bio_story),
  bio_hobbies = CASE
    WHEN a.bio_hobbies IS NULL OR cardinality(a.bio_hobbies) = 0 THEN bios.bio_hobbies
    ELSE a.bio_hobbies
  END
FROM bios
WHERE a.slug = bios.slug;
